# VULNERABLE: eval the model's output, no allowlist, no real auth
def handle(model_output):
    return eval(model_output)     # arbitrary code execution

# SECURE: allowlist functions, validate args, enforce auth in code
ALLOWED = {"get_order_status", "track_package"}

def dispatch(call, user):
    name = call["name"]
    args = call["args"]

    if name not in ALLOWED:
        raise PermissionError("function not permitted")

    # Real authorization, checked in code against the user's actual role
    if name == "system_check" and not user.is_admin:
        raise PermissionError("admin required")

    # Validate argument types/shapes before executing
    if name == "get_order_status":
        order_id = int(args["order_id"])   # raises on non-integer
        return get_order_status(order_id)

# Principles:
# - Never eval/exec model output.
# - Maintain an explicit allowlist of callable functions.
# - Enforce authorization in code using the real session, not prompt claims.
# - Validate and type-check every argument.
